const judgeTier = (priorRuling) => priorRuling ? (FABLE_WEEK ? { model: FABLE, effort: 'high' } : { model: FABLE }) : { model: OPUS }
const BASE = args && args.base
if (!BASE) throw new Error('args.base is required: the commit every wip/ branch is cut from')
// The batch's one base build (POSITIONS.md, "Nothing is built or run twice on the same code."): a
// worktree at BASE that the coordinator built once before the launch. Every rung worktree is
// seeded from it (tools/seed-worktree.sh), and the old code runs from it through
// tools/old-fortress.sh, each rung with a private caches folder in its worktree's tmp/; nobody
// builds, compiles or runs anything else in it.
const BASE_BUILD = args && args.baseBuild
if (typeof BASE_BUILD !== 'string' || !/^\/[A-Za-z0-9._\/-]+$/.test(BASE_BUILD) || /\/$/.test(BASE_BUILD))
  throw new Error('args.baseBuild is required: the absolute path of the worktree at the base, built once before the launch (climb-batch-workflow.md, "Before the launch"), with no trailing slash, space or quote')
const TOOLS = 'explorations/coordinator/tools'
const SEED = BASE_BUILD + '/' + TOOLS + '/seed-worktree.sh'
const OLD = BASE_BUILD + '/' + TOOLS + '/old-fortress.sh'   // runs the base's code from the base build
const oldCaches = (rung) => rung.path + '/tmp/old-caches'   // a rung's private caches folder for the old code
const PUSH_BRANCHES = ['claude/worker-brief-fable-vnnuv8', 'blinded-fable']   // every push of main goes to these too (explorations/protocol.md, hard rules)
const MAIN = '/home/user/fortress'
const LEDGER = TOOLS + '/ledger.py'

// ===========================================================================
// MANIFEST - the coordinator replaces everything between this line and the
// "END MANIFEST" line, and changes nothing else in this file.
//
// Generated by explorations/compile-ladder/plan-33/manifest/gen33.py --run 1 from
// CLIMB-BATCH-33.md (section 4, each rung's section word for word; section 1, the
// manifest fields; section 6, the intro of run 1) and the briefings of lists33.py; check33.js checks it.
// The record holds two runs: climb batch 33 (rungs S, D, V, Q, I, C) and 33b (N, W, G, R).
// Climb batch 33: rungs S, D, V, Q, I, C, the manifest's order; none lands only with another.
// Per rung: id, slug, path, branch, expectedMinutes (the scatter's start order only),
// writesState, testIsStage, gateJoins (a gate step the rung brings), blurb (one line
// for the batch table), section (the rung's section of the record, read by every role
// on the rung), pointsToReport, briefing and reasons (the facts-extract.sh keys the
// worker reads first, each with its reason; of section 3's forks, the record's one
// key, "Forks the batch takes" whole, for every rung), checks (the sub-list the
// skeptic, a judge and a repair round read), expectedMoves (ladder moves declared,
// none here), and the optional landsOnlyWith, expectedCheckerCount and
// expectedCheckerCrash: no rung lands only with another (section 1's common fields),
// and none declares a checker count or a crash (the count is reported).
// No rung brings a gate step: S's test track runs inside testFast, which the gate runs.
// Every string here is ASCII: the record's sections hold no other character.
// No value is set at launch. The base and the base build are args.base and
// args.baseBuild. At most two agents run at once on this box, FIFO (FACTS.md, "The
// Workflow harness runs two agents at once on this box"); the scatter starts the
// longest expected worker first.
// ===========================================================================

const BATCH = '33'
const BATCH_RECORD = 'explorations/coordinator/CLIMB-BATCH-33.md'
const BRIEFING_LISTS = 'explorations/compile-ladder/plan-33/manifest/lists33.py'

const S_SECTION = [
"**The mission.** The compiled path reads only the compiler's prelude: Shell.useCompilerLibraries() points WellKnownNames and Types at the prelude's names for every compiled-path command (Shell.java:373-379). The decisions on record take microGPT's slice first: the compile command selects the one library beside the prelude, so that each wall that only the one library shows is met as one rung with its own test under the gate (P-33; F-353). Probe Y built the selector in scratch with eight shortcuts (probe-y.md, sections 2 and 3). You build it properly, without the parts that later rungs own.",
"",
"**The decisions this rung builds.** P-33; P-37, by which the prelude stays the default and gains nothing. Section 3's forks S1 to S6.",
"",
"**What you build, in order.**",
explorations/coordinator/climb-batch-workflow.js:113:"3. **The caches folder** (fork S2). ProjectProperties.CACHES defaults to ${REPOSITORY}/caches-one under the selection; bin/run_classpath and bin/fortress_classpath take the same default; build.xml's stamp and ant cleanCache cover both folders.",
build.xml:47:  <property name="cacheOne" location="default_repository/caches-one"/>
bin/fortress_classpath:26:# compiled path reads the one library, default_repository/caches-one, as ProjectProperties.CACHES does.
bin/fortress_classpath:28:  CACHES="${FORTRESS_CACHES:-$FORTRESS_HOME/default_repository/caches-one}"
bin/run_classpath:26:# compiled path reads the one library, default_repository/caches-one, as ProjectProperties.CACHES does.
bin/run_classpath:28:  CACHES="${FORTRESS_CACHES:-$FORTRESS_HOME/default_repository/caches-one}"

